"""Original compressed-footage fixtures. All generated bytes stay in an external output root.

Patterns and sound are authored here; FFmpeg supplies only encoding/muxing. The manifest records
exact commands and tool identities. Long footage is opt-in and repeats an original closed GOP.
"""
from fractions import Fraction
import hashlib
import json
import os
from pathlib import Path
import subprocess
import wave

import numpy as np

ROOT = Path(__file__).resolve().parents[1]
FFMPEG = os.environ.get("CUTBOLT_FFMPEG", "ffmpeg")
FFPROBE = os.environ.get("CUTBOLT_FFPROBE", "ffprobe")


def identity(path):
    with path.open("rb") as stream:
        digest = hashlib.file_digest(stream, "sha256").hexdigest()
    return {"bytes": path.stat().st_size, "sha256": digest}


def pixels(n, width, height):
    """Moving rectangle over independently coded spatial and temporal channels."""
    y, x = np.indices((height, width), dtype=np.int32)
    image = np.stack(((x * 3 + n * 7) % 256, (y * 5 + n * 11) % 256,
                      ((x // 8 + y // 8) * 31 + n * 13) % 256), axis=-1).astype(np.uint8)
    left = (n * 3) % max(1, width - 16)
    image[height // 3:height // 3 + 12, left:left + 16] = [16, 220, 70]
    return image.tobytes()


def sound(path, rate, channels, seconds):
    count = (seconds.numerator * rate + seconds.denominator - 1) // seconds.denominator
    with path.open("xb") as file, wave.open(file, "wb") as out:
        out.setnchannels(channels)
        out.setsampwidth(2)
        out.setframerate(rate)
        for first in range(0, count, rate):
            n = np.arange(first, min(count, first + rate), dtype=np.int64)
            # Deliberate pauses support the later scripted talking-head workflow, without a model.
            envelope = ((n * 4 // rate) % 16 < 11).astype(np.int32)
            values = [np.rint(5000 * np.sin(2 * np.pi * frequency * n / rate)) * envelope
                      for frequency in (317, 631)[:channels]]
            out.writeframes(np.stack(values, axis=-1).astype('<i2').tobytes())


def probe(path):
    command = [FFPROBE, "-v", "error", "-threads", "4", "-show_streams", "-show_format", "-show_frames",
               "-show_entries", "stream:format:frame=media_type,best_effort_timestamp,key_frame,pict_type,nb_samples",
               "-of", "json", str(path)]
    return json.loads(subprocess.check_output(command, timeout=1200))


def encode(root, name, *, codec="h264", rate=Fraction(30), count=150, size=(160, 90),
           audio_rate=48000, channels=2, gop=60, open_gop=False, pix_fmt="yuv420p", extra=(), phase=0):
    suffix = ".mov" if codec == "prores" else ".mkv" if codec == "ffv1" else ".mp4"
    path = root / (name + suffix)
    audio = root / (name + ".wav")
    sound(audio, audio_rate, channels, Fraction(count, 1) / rate)
    video = (["-c:v", "libx264", "-profile:v", "high", "-preset", "fast", "-crf", "18",
              "-x264-params", f"keyint={gop}:min-keyint={gop}:scenecut=0:bframes=3:b-adapt=0:open-gop={int(open_gop)}"]
             if codec == "h264" else
             ["-c:v", "libx265", "-preset", "fast", "-crf", "18", "-tag:v", "hvc1", "-x265-params",
              f"pools=2:frame-threads=2:keyint={gop}:min-keyint={gop}:scenecut=0:bframes=3:b-adapt=0:open-gop={int(open_gop)}"]
             if codec == "hevc" else ["-c:v", "prores_ks", "-profile:v", "3"]
             if codec == "prores" else ["-c:v", "ffv1", "-level", "3"])
    command = [FFMPEG, "-v", "error", "-nostdin", "-n", "-f", "rawvideo", "-pixel_format", "rgb24",
               "-video_size", f"{size[0]}x{size[1]}", "-framerate", str(rate), "-i", "pipe:0",
               "-i", str(audio), "-map", "0:v:0", "-map", "1:a:0", "-threads", "2", *video,
               "-pix_fmt", pix_fmt, "-color_primaries", "bt709", "-color_trc", "bt709",
               "-colorspace", "rgb" if codec == "ffv1" else "bt709", "-color_range", "pc" if codec == "ffv1" else "tv",
               "-c:a", "pcm_s16le" if codec in {"prores", "ffv1"} else "aac",
               *([] if codec in {"prores", "ffv1"} else ["-b:a", "128k"]), *extra, str(path)]
    with (root / (name + ".encoder.log")).open("xb") as log:
        process = subprocess.Popen(command, stdin=subprocess.PIPE, stdout=subprocess.DEVNULL, stderr=log)
        try:
            for n in range(count):
                process.stdin.write(pixels(n + phase, *size))
            process.stdin.close()
            assert process.wait(timeout=600) == 0, name
        finally:
            if process.poll() is None:
                process.kill()
                process.wait()
    return {"path": path.name, **identity(path), "command": command, "encoded_frames": count,
            "rate": str(rate), "size": list(size), "audio_rate": audio_rate, "channels": channels,
            "codec": codec, "gop": gop, "open_gop": open_gop, "pix_fmt": pix_fmt, "phase": phase,
            "audio_source": {"path": audio.name, **identity(audio)}}


def remux(root, base, name, extra):
    path = root / (name + ".mp4")
    command = [FFMPEG, "-v", "error", "-nostdin", "-n", *extra, "-i", str(root / base["path"]),
               "-map", "0", "-c", "copy", str(path)]
    subprocess.run(command, capture_output=True, check=True, timeout=600)
    return {**base, "path": path.name, **identity(path), "command": command, "derived_from": base["path"]}


def generate(root, long=False):
    root = root.resolve()
    assert root != ROOT and ROOT not in root.parents, "Keep generated media outside the checkout"
    root.mkdir(parents=True, exist_ok=False)
    cases = {}
    for rate in [Fraction(25), Fraction(30), Fraction(60), Fraction(30000, 1001)]:
        name = "h264-" + str(rate).replace('/', '-')
        cases[name] = encode(root, name, rate=rate)
    for name, fields in {
        "h264-mono-44100": {"audio_rate": 44100, "channels": 1},
        "h264-edit-list": {"extra": ["-output_ts_offset", "0.4", "-use_editlist", "1"]},
        "h264-sar": {"extra": ["-vf", "setsar=4/3"]},
        "h264-vfr": {"extra": ["-vf", "select='not(eq(mod(n,7),3))'", "-fps_mode", "vfr"]},
        "h264-long-gop": {"gop": 250, "count": 300},
        "hevc-main": {"codec": "hevc"},
        "hevc-open-gop": {"codec": "hevc", "open_gop": True},
        "hevc-main10": {"codec": "hevc", "pix_fmt": "yuv420p10le"},
        "prores-hq": {"codec": "prores", "pix_fmt": "yuv422p10le"},
    }.items():
        cases[name] = encode(root, name, **fields)
    cases["h264-rotation"] = remux(root, cases["h264-30"], "h264-rotation", ["-display_rotation:v:0", "90"])
    if long:
        seed = encode(root, "long-seed", count=60, size=(1920, 1080))
        path = root / "h264-20min.mp4"
        # Stream-copy repeats a complete closed GOP, keeping long-source preparation bounded in RAM/disk.
        # Sound is freshly encoded for one continuous clock, avoiding repeated AAC priming blocks.
        audio = root / "long-sound.wav"
        sound(audio, 48000, 2, Fraction(1200))
        command = [FFMPEG, "-v", "error", "-nostdin", "-n", "-stream_loop", "-1", "-i", str(root / seed["path"]),
                   "-i", str(audio), "-map", "0:v:0", "-map", "1:a:0", "-t", "1200", "-frames:v", "36000", "-c:v", "copy",
                   "-c:a", "aac", "-b:a", "128k", str(path)]
        subprocess.run(command, capture_output=True, check=True, timeout=600)
        cases["h264-20min"] = {**seed, "path": path.name, **identity(path), "command": command,
                               "encoded_frames": 36000, "repeated_original_gop": 60,
                               "audio_source": {"path": audio.name, **identity(audio)}}
    manifest = {"generator": "original-coded-footage-v1", "cases": cases,
                "tools": {tool: subprocess.check_output([exe, "-version"]).decode().splitlines()[0]
                          for tool, exe in [("ffmpeg", FFMPEG), ("ffprobe", FFPROBE)]}}
    (root / "manifest.json").write_text(json.dumps(manifest, indent=2) + "\n", encoding="utf-8")
    return manifest
